(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.012-t*0.2)*12;
  const w1y = Math.cos(y*0.018-t*0.25)*18 + Math.sin(x*0.015+t*0.35)*12;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.03+sy*0.02+t*0.5)*8;
  const w2y = Math.cos(sx*0.02-sy*0.03-t*0.4)*8;
  const sx2 = sx+w2x, sy2 = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*60,0.05,2.8],
    [200+Math.sin(t*0.7+1)*90,220+Math.cos(t*0.3+3)*40,0.09,1.6],
    [300+Math.cos(t*0.42+6)*80,100+Math.sin(t*0.58+2)*70,0.07,2.4]
  ];
  let act = 0, inh = 0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx2-sX)**2+(sy2-sY)**2);
    act += Math.sin(d*f-t*sp) + Math.sin(d*f*1.5-t*sp*0.8+0.5)*0.4;
    inh += Math.sin(d*f*0.7+t*sp*0.6+1.5) + Math.cos(d*f*1.3+t*sp*0.4-0.7)*0.4;
  }
  act /= src.length*1.4; inh /= src.length*1.4;
  const bg = (Math.sin(sx2*0.04+sy2*0.025+t*0.8)+Math.sin(sx2*0.03-sy2*0.04+t*1.1)+Math.sin(sx2*0.07+sy2*0.01-t*0.6)+Math.cos(sx2*0.02+sy2*0.06+t*0.9))/4 + Math.sin((sx2+sy2)*0.12+t*2.5)*0.15 + Math.sin((sx2-sy2)*0.1-t*2)*0.15;
  const dist = Math.sqrt((sx2-cx)**2+(sy2-cy)**2), ang = Math.atan2(sy2-cy,sx2-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07+ang*2+t*0.8)*0.5+Math.cos(dist*0.03-ang*5-t*2)*0.5)*0.3;
  const moire = (Math.sin(sx2*0.2)*Math.sin(sy2*0.2)+Math.sin((sx2+sy2)*0.1414)*Math.sin((sx2-sy2)*0.1414))*0.15;
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+spiral+moire)*2.0);
  const cell = Math.tanh((Math.sin(sx2*0.15)*Math.sin(sy2*0.15)+Math.sin((sx2+sy2)*0.1+t)*0.5+Math.sin(sx2*0.08-sy2*0.12+t*0.7)*0.3)*1.5)*0.25;
  const blend = reaction*0.7+cell*0.2+moire*0.1, v = blend*0.5+0.5;
  const pal = [[12,15,52],[25,55,95],[20,110,120],[45,165,140],[180,195,80],[235,190,60],[225,130,65],[195,70,70],[140,40,80],[75,25,85],[12,15,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0,pal.length-2), f = idx-i;
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15;
  const edgeStr = Math.abs(reaction), edge = edgeStr>0.65?1.0+(edgeStr-0.65)*0.8:1.0;
  const peak = Math.max(0,reaction-0.5)*0.4;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+peak*60)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+peak*40)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+peak*10)|0)
  ];
}
